  no:{setup:'TILBEHØR-OPPSETT',intro:'Velg en entitet, eller la feltet stå på Automatisk.',accessory:'Tilbehør',automatic:'Automatisk',label:'Navn',entity:'Entitet',appearance:'Utseende',language:'Språk',accent:'Aksent',auto:'Auto',light:'Lyst',dark:'Mørkt',norwegian:'Norsk',english:'Engelsk',apply:'Bruk',reset:'Nullstill',unknown:'Ukjent'},
